using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Windows.Forms;using System.Reflection;using System.Drawing;using Frociart;
internal static class FlowgorithmTests {
 static int checks;static void Check(bool v,string m){if(!v)throw new Exception(m);checks++;}
 static string Run(Diagram d,string[] inputs){var r=new Interpreter(d);int at=0;for(int i=0;i<10000&&r.State!=RuntimeState.Completed&&r.State!=RuntimeState.Error;i++){if(r.State==RuntimeState.WaitingForInput){Check(at<inputs.Length,"Input available");r.ProvideInput(inputs[at++]);}else r.Step();}Check(r.State==RuntimeState.Completed,"Completion: "+r.Error);return String.Join("|",r.Output);}
 static void Pump(){var t=System.Diagnostics.Stopwatch.StartNew();while(t.ElapsedMilliseconds<200){Application.DoEvents();System.Threading.Thread.Sleep(5);}}
 static object Field(object o,string n){return o.GetType().GetField(n,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(o);}
 [STAThread]static int Main(string[] args){try{string root=args[0],outDir=Path.Combine(root,"pc");Directory.CreateDirectory(outDir);
  foreach(string line in File.ReadAllLines(Path.Combine(root,"cases.tsv"),Encoding.UTF8)){var parts=line.Split('\t');string path=Path.Combine(root,"fixtures",parts[0]+".fprg");byte[] bytes=File.ReadAllBytes(path);var d=DiagramIO.Load(path);Check(Run(d,parts[2].Length==0?new string[0]:parts[2].Split('|'))==parts[1],"Execution "+parts[0]);Check(bytes.SequenceEqual(File.ReadAllBytes(path)),"Original untouched");string encoded=Encoding.UTF8.GetString(DiagramIO.EncodeDocument(d));Check(!encoded.Contains("PRIVATE_HISTORY_MARKER")&&!encoded.Contains("PRIVATE_AUTHOR_MARKER"),"Source metadata omitted");DiagramIO.Save(Path.Combine(outDir,parts[0]+".frociart"),d);Check(Run(DiagramIO.Load(Path.Combine(outDir,parts[0]+".frociart")),parts[2].Length==0?new string[0]:parts[2].Split('|'))==parts[1],"Reopen "+parts[0]);var pseudo=FlowPseudocode.Decode(FlowPseudocode.Encode(d));Check(Run(pseudo,parts[2].Length==0?new string[0]:parts[2].Split('|'))==parts[1],"Pseudocode round trip "+parts[0]);FlowLayout.Arrange(d);Check(Run(d,parts[2].Length==0?new string[0]:parts[2].Split('|'))==parts[1],"Riordina "+parts[0]);}
  foreach(string file in Directory.GetFiles(Path.Combine(root,"fixtures"),"reject-*.fprg")){if(Path.GetFileName(file)=="reject-newline.fprg"){var accepted=DiagramIO.Load(file);Check(!FlowOutput.Newline(accepted.Nodes.Single(n=>n.Kind==NodeKind.Output).Text)&&Run(accepted,new string[0])=="1","Output without newline is now supported");continue;}if(Path.GetFileName(file)=="reject-reference-array-parameters.fprg"){var accepted=DiagramIO.Load(file);Check(accepted.Version>=3&&accepted.Functions.SelectMany(f=>f.Parameters).Where(v=>v.IsArray).All(v=>v.ByReference)&&accepted.Functions.SelectMany(f=>f.Parameters).Any(v=>v.ByReference),"Complete reference-vector sample imports with explicit semantics");continue;}if(Path.GetFileName(file)=="reject-array-param.fprg"){var accepted=DiagramIO.Load(file);Check(accepted.Version==3&&accepted.Functions.Single().Parameters.Single().ByReference&&accepted.Functions.Single().Parameters.Single().IsArray,"Vector references are now supported explicitly");Check(Run(accepted,new string[0])=="","Imported unused reference function never executes");continue;}if(Path.GetFileName(file)=="reject-comment-size.fprg"){var accepted=DiagramIO.Load(file);Check(accepted.Version==4&&accepted.Nodes.Single(n=>n.Kind==NodeKind.Note).Text.Length==2049,"Standalone notes support more than the old attached-comment limit");continue;}bool rejected=false;try{DiagramIO.Load(file);}catch(InvalidDataException e){rejected=true;Check(e.Message.Contains("Flowgorithm"),"Localized diagnostic: "+file);}Check(rejected,"Reject "+Path.GetFileName(file));}
  bool invalidUtf8=false;try{FlowgorithmImport.Decode(new byte[]{0xff,0xfe,0xff});}catch(InvalidDataException){invalidUtf8=true;}Check(invalidUtf8,"Bad UTF-8");
  var notes=DiagramIO.Load(Path.Combine(root,"fixtures/notes.fprg"));Check(notes.Nodes.Where(n=>n.Kind==NodeKind.Note).Select(n=>n.Text).SequenceEqual(new[]{"Prima nota","Seconda nota","Coda ramo","Coda ciclo","Fine programma"}),"Every comment preserved as independent note in source order");Check(notes.Version==4&&notes.Nodes.Where(n=>n.Kind==NodeKind.Note).All(n=>notes.Edges.All(e=>e.From!=n.Id&&e.To!=n.Id)),"Notes explicitly outside execution and versioned");Check(notes.Nodes.All(n=>n.Kind!=NodeKind.Process),"Notes never become executable assignments");
  using(var main=new MainForm(null,true)){main.Show();Pump();string source=Path.Combine(root,"fixtures/for.fprg");Check(main.LoadPath(source),"Actual MainForm open");Pump();Check(Field(main,"currentPath")==null&&(bool)Field(main,"dirty"),"Imported copy asks new save destination");Check(main.Runner==null,"Opening never executes code");Check(Run(main.Project,new string[0])=="6","Native loaded program");var output=main.Project.Nodes.First(n=>n.Kind==NodeKind.Output);output.Text="totale + 1";string save=Path.Combine(outDir,"native-saved.frociart");main.GetType().GetField("currentPath",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(main,save);bool ok=(bool)main.GetType().GetMethod("SaveDocument",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(main,new object[]{false});Check(ok&&File.Exists(save),"Real native SaveDocument writes");Check(main.LoadPath(save)&&Run(main.Project,new string[0])=="7","Native reopen edited import");using(var image=new Bitmap(main.Width,main.Height)){main.DrawToBitmap(image,new Rectangle(0,0,image.Width,image.Height));image.Save(Path.Combine(root,"pc-import.png"));}main.SetDocument(new Diagram(),null,false);main.Close();}
  Check(DocumentLaunch.Parse(new[]{"--open",Path.Combine(root,"fixtures/basic.fprg")}).Path.EndsWith(".fprg"),"Command line accepts fprg");Console.WriteLine("FLOWGORITHM_PC PASS checks="+checks);return 0;
 }catch(Exception e){Console.WriteLine(e);return 1;}}
}
